def read(rel):
 p=R/rel
 return list(csv.DictReader(p.open(encoding='utf-8-sig',newline='')))
def dump(name, rows, fields=None):
 with (O/name).open('w',encoding='utf-8-sig',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields or list(rows[0]));w.writeheader();w.writerows(rows)
def uniq(seq):
 return list(dict.fromkeys(str(x) for x in seq if x is not None and str(x).strip()))
def urls(files, filt=None):
 out=[]
 for f in files:
  for row in read(f):
   if filt and not filt(row):continue
   for k,v in row.items():
    if ('url' in k.lower() or k.endswith('_source')) and v.startswith('http'):
     out.extend(re.findall(r'https?://[^\s]+',v))
 return ' | '.join(uniq(out))
