 assert status in ['supported','contradicted','unidentified']
 M.append(dict(claim_id=f'{issuer.upper()[:3]}{sum(x["issuer"]==issuer for x in M)+1:02}',issuer=issuer,dimension=dim,precise_scope=period,exact_claim=claim,needed_evidence=needed,available_evidence=available,status=status,source_files=' | '.join(files),source_locators=locators,source_urls=' | '.join(uniq((urls(files).split(' | ') if files else [])+(extra_urls or []))),inference_limit=limit,review_date=DATE,verification_basis=verification))
