 key=source['source_key']
 rows.append({'original_commitment_key':key,'manuscript_source_key':aliases.get(key,key),'status':'Excluded later framework; not a source of 2019 promises' if key=='IB-FW23-EXCLUDED' else 'Verified source alias','source_url':source['source_url'],'locator':source['locator']})
